interface.definition:
a!localVariables(
  {
    /* ── TITLE BAR ── */
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_sideBySideLayout"(
          alignVertical: "MIDDLE",
          items: {
            /* Icon */
            #"SYSTEM_SYSRULES_sideBySideItem"(
              width: "MINIMIZE",
              item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                marginBelow: "NONE",
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextIcon"(
                    icon: "building-o",
                    size: "MEDIUM_PLUS"
                  )
                }
              )
            ),
            /* Page Title */
            #"SYSTEM_SYSRULES_sideBySideItem"(
              item: #"SYSTEM_SYSRULES_headingField"(
                marginBelow: "NONE",
                text: "Organization Management",
                fontWeight: "SEMI_BOLD",
                size: "MEDIUM",
                headingTag: "H1"
              )
            ),
            /* Primary Action Button */
            #"SYSTEM_SYSRULES_sideBySideItem"(
              width: "MINIMIZE",
              item: #"SYSTEM_SYSRULES_recordActionField_v1"(
                actions: #"SYSTEM_SYSRULES_recordActionItem"(
                  action: #"urn:appian:record-action:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/a7039225-8a7e-4bc5-87b6-69b91f8b8e03"
                ),
                style: "CALL_TO_ACTION",
                align: "END"
              )
            )
          }
        )
      },
      height: "AUTO",
      style: "ACCENT",
      padding: "STANDARD",
      marginBelow: "NONE",
      showBorder: false
    ),
    /* ── CONTENT AREA ── */
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"_a-0000eef8-4604-8000-9e54-011c48011c48_1122556"()
      },
      height: "AUTO",
      style: "NONE",
      shape: "SEMI_ROUNDED",
      padding: "STANDARD",
      marginBelow: "STANDARD",
      showBorder: false,
      showShadow: true
    )
  }
)
